# ── Кешированные геттеры (base64 декодируется один раз) ─────────────────────

@lru_cache(maxsize=1)
def get_font_regular_bytes() -> bytes:
    """Байты обычного шрифта DejaVu Sans."""
    return base64.b64decode(_GP_FONT_REGULAR_B64)


@lru_cache(maxsize=1)
def get_font_bold_bytes() -> bytes:
    """Байты жирного шрифта DejaVu Sans Bold."""
    return base64.b64decode(_GP_FONT_BOLD_B64)


@lru_cache(maxsize=1)
def get_opis_template_bytes() -> bytes:
    """Байты шаблона Опись.docx (форма ф.107)."""
    return base64.b64decode(_LAW_OPIS_TEMPLATE_B64)
